package org.example

import buildFoo
import org.junit.jupiter.api.Test
import org.junit.jupiter.api.Assertions.*
import retryPolicyBuilder
import kotlin.reflect.cast
import kotlin.reflect.full.memberFunctions

class canRetryTests {
    @Test
    fun metaprogrammingTest() {
        val kclass = retryPolicyBuilder()

        val maxRetries = kclass.constructors.first().call(3)
        val canRetry = kclass.memberFunctions.first() { it.name == "canRetry" }

        assertEquals(true, canRetry.call(maxRetries, 1))
        assertEquals(true, canRetry.call(maxRetries, 2))
        assertEquals(false, canRetry.call(maxRetries, 3))
    }
}
